        console2.log("Bob balance after normal transfer:", token.balanceOf(bob));
        console2.log("------------------------------------");

        console2.log("\n--- Trigger: Set maxTxAmount = 0 ---");
        token.setMaxTxAmount(0);

        console2.log("\n--- AFTER-Trigger (Transfer Attempt with maxTxAmount=0) ---");
        console2.log("New maxTxAmount:", token._maxTxAmount());
        console2.log("Alice balance before:", token.balanceOf(alice));
        console2.log("Bob balance before:", token.balanceOf(bob));

